const body = $json.body || $json;
const chaveLimpa = String(body.chave || '').replace(/\D/g, '');

if (chaveLimpa.length !== 44) {
  return [{ json: { ok: false, erro: 'chave_invalida', mensagem: 'Chave de acesso precisa ter 44 dígitos.' } }];
}

// Único empresa hoje (Delivery Pet) — se virar multi-tenant, buscar
// CNPJ/estado da tabela `empresas` em vez de hardcode (ver Postgres
// node/credential "Postgres cloud" já usado em outros workflows).
const CNPJ = '52816710000198';
const cUFAutor = '33'; // RJ
const tpAmb = '1'; // 1 = produção, 2 = homologação

const soap = `<?xml version="1.0" encoding="utf-8"?>
<soap12:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap12="http://www.w3.org/2003/05/soap-envelope">
  <soap12:Body>
    <nfeDistDFeInteresse xmlns="http://www.portalfiscal.inf.br/nfe/wsdl/NFeDistribuicaoDFe">
      <nfeDadosMsg>
        <distDFeInt xmlns="http://www.portalfiscal.inf.br/nfe" versao="1.35">
          <tpAmb>${tpAmb}</tpAmb>
          <cUFAutor>${cUFAutor}</cUFAutor>
          <CNPJ>${CNPJ}</CNPJ>
          <consChNFe>
            <chNFe>${chaveLimpa}</chNFe>
          </consChNFe>
        </distDFeInt>
      </nfeDadosMsg>
    </nfeDistDFeInteresse>
  </soap12:Body>
</soap12:Envelope>`;

return [{ json: { ok: true, chave: chaveLimpa, soapBody: soap } }];

const resposta = $input.first().json;
const corpo = typeof resposta.data === 'string' ? resposta.data : String(resposta.data || '');

function extrairTag(xml, tag) {
  const m = xml.match(new RegExp('<' + tag + '[^>]*>([^<]*)</' + tag + '>', 'i'));
  return m ? m[1] : null;
}

const cStat = extrairTag(corpo, 'cStat');
const xMotivo = extrairTag(corpo, 'xMotivo');
const docZipMatch = corpo.match(/<docZip[^>]*schema="([^"]*)"[^>]*>([^<]*)<\/docZip>/i);

if (!docZipMatch) {
  return [{ json: {
    ok: false,
    erro: cStat === '137' ? 'nao_encontrada' : 'falha_busca',
    mensagem: xMotivo || 'NF-e não encontrada na Sefaz pra essa chave, ou nenhum documento retornado.',
    cStat,
  } }];
}

const schema = docZipMatch[1];
const docZipBase64 = docZipMatch[2];

// require('zlib') é builtin do Node — se o n8n bloquear ("Cannot find
// module 'zlib'"), a alternativa é trocar este passo por um nó
// Compression (core node, decompress/gzip) em vez de Code.
const zlib = require('zlib');
const xml = zlib.gunzipSync(Buffer.from(docZipBase64, 'base64')).toString('utf-8');

return [{ json: { ok: true, xml, schema, cStat } }];
